import * as T from './assets/three.js';
import {OrbitControls} from './assets/addons/OrbitControls.js';
import {products} from './product-catalog.js';
import {identifyProduct} from './product-import.js';
import {createGeneratedProduct} from './generated-model.js';
import {capacityLabel} from './product-specs.js';
import {createSizedModel,setPhysicalDimension,resetPhysicalDimension} from './product-scale.js';
const $=s=>document.querySelector(s);
export async function fileData(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)})}
function disposeModel(root){const mats=new Set(),textures=new Set(),geos=new Set();root?.traverse(n=>{if(n.geometry)geos.add(n.geometry);if(n.material)for(const m of Array.isArray(n.material)?n.material:[n.material])mats.add(m)});for(const m of mats){for(const t of Object.values(m))if(t?.isTexture)textures.add(t);m.dispose()}for(const t of textures)t.dispose();for(const g of geos)g.dispose()}
export function initPhotoFlow(envCanvas){
 const dialog=$('#photo-dialog'),host=$('#photo-stage'),renderer=new T.WebGLRenderer({antialias:true,alpha:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.1;renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;host.append(renderer.domElement);
 const scene=new T.Scene();scene.background=new T.Color('#d9ddce');const camera=new T.PerspectiveCamera(38,1,.05,100),orbit=new OrbitControls(camera,renderer.domElement);orbit.enableDamping=true;scene.add(new T.HemisphereLight('#fff8ef','#7c796d',1));const light=new T.DirectionalLight('#fff5e5',2.6);light.position.set(-3,5,6);light.castShadow=true;light.shadow.mapSize.set(1024,1024);Object.assign(light.shadow.camera,{left:-8,right:8,top:8,bottom:-8});scene.add(light);const et=new T.CanvasTexture(envCanvas);et.colorSpace=T.SRGBColorSpace;et.mapping=T.EquirectangularReflectionMapping;const pm=new T.PMREMGenerator(renderer);scene.environment=pm.fromEquirectangular(et).texture;pm.dispose();et.dispose();const floor=new T.Mesh(new T.PlaneGeometry(100,100),new T.MeshStandardMaterial({color:'#d9ddce',roughness:1}));floor.rotation.x=-Math.PI/2;floor.position.y=-.012;floor.receiveShadow=true;scene.add(floor);
 let session=null,model=null,resolveFlow=null,version=0,frame;
 function size(){const w=host.clientWidth,h=host.clientHeight;if(w&&h){renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix()}}new ResizeObserver(size).observe(host);
 function animate(){if(!dialog.open)return;frame=requestAnimationFrame(animate);orbit.update();renderer.render(scene,camera)}
 function fit(){size();const sphere=new T.Box3().setFromObject(model).getBoundingSphere(new T.Sphere());orbit.target.copy(sphere.center);const distance=sphere.radius/Math.sin(T.MathUtils.degToRad(camera.fov/2))*Math.max(1,1/camera.aspect)*1.13;camera.position.copy(sphere.center).add(new T.Vector3(-.08,.28,1).normalize().multiplyScalar(distance));orbit.update()}
 function syncSize(){if(!model)return;const spec=model.userData.physicalSize;session.config.physicalSize=structuredClone(spec);for(const a of ['x','y','z'])$('#photo-mm-'+a).value=spec.baseMm[a].toFixed(1);$('#photo-size-summary').textContent=capacityLabel(spec)+' · '+spec.quality;$('#photo-size-basis').textContent=spec.source;$('#photo-size-link').hidden=!spec.url;$('#photo-size-link').href=spec.url||'#';$('#photo-part-count').textContent='净含量 '+capacityLabel(spec)+' · 包装约 '+['x','y','z'].map(a=>spec.baseMm[a].toFixed(1)).join(' × ')+' mm（宽 × 高 × 深）'}
 async function build(){const current=session,id=++version;$('#photo-create').disabled=true;if(!current?.product&&!current?.generatedRecipe)return;try{let next;if(current.generatedRecipe)next=(await createGeneratedProduct(current.generatedRecipe,current.source,current.generationId,current.config.physicalSize)).model;else{const raw=await current.product.create(renderer);raw.position.y+=current.product.yOffset;next=createSizedModel(raw,current.product.size,current.config.physicalSize)}if(id!==version||session!==current){disposeModel(next);return}scene.remove(model);disposeModel(model);model=next;scene.add(model);syncSize();fit();const p=current.photo,can=$('#photo-source-canvas');can.closest('.photo-source').hidden=!p;if(p){can.width=p.w;can.height=p.h;can.getContext('2d').drawImage(p.canvas,0,0);}$('#recipe-note').textContent=current.dossier.product;$('#photo-analysis').textContent=current.generatedRecipe?'本机 Codex 实际查资料后生成':current.manual?'已人工核对同款 · 使用对应的研究模型':'已匹配同款 · 使用对应的研究模型';$('#photo-message').textContent=current.dossier.limitations;$('#photo-create').disabled=false}catch(e){$('#photo-message').textContent='专属模型未载入：'+e.message}}
 for(const a of ['x','y','z'])$('#photo-mm-'+a).onchange=e=>{try{setPhysicalDimension(model,a,+e.target.value);syncSize();fit()}catch(err){$('#photo-message').textContent=err.message;syncSize()}};
 $('#photo-size-reset').onclick=()=>{resetPhysicalDimension(model);syncSize();fit()};
 function finish(result){version++;dialog.close();cancelAnimationFrame(frame);scene.remove(model);if(!result)disposeModel(model);model=null;const resolve=resolveFlow;resolveFlow=null;session=null;resolve?.(result)}
 $('#photo-cancel').onclick=()=>finish(null);dialog.oncancel=e=>{e.preventDefault();finish(null)};$('#photo-create').onclick=()=>{if(model&&session)finish({model,source:session.source,config:session.config,extraSources:session.extraSources,research:session.dossier})};
 function renderResearch(){const d=session.dossier;$('#reference-dossier').hidden=!d;$('#research-intake').hidden=!!d;$('#researched-model-tools').hidden=!d;$('#photo-create').hidden=!d;$('#research-name').value=session.name.replace(/\.[^.]+$/,'');$('#research-source').hidden=!session.source;if(session.source)$('#research-source').src=session.source;else $('#research-source').removeAttribute('src');$('#research-request-state').textContent='';
 if(!d){$('#photo-message').textContent='先识别产品、查找同版资料并建立参考档案，完成后再制作专属模型。当前尚未检索，未开始建模。';return}
 $('#research-product').textContent=d.product+' · '+d.spec;$('#research-state').textContent='实际检索日期 '+d.researchedAt;$('#research-identity').textContent=d.identity;$('#research-coverage').replaceChildren();for(const item of d.coverage){const card=document.createElement('div');card.className='coverage-card'+(item.status.includes('缺')?' missing':'');const title=document.createElement('b'),state=document.createElement('span'),source=document.createElement('small');title.textContent=item.face;state.textContent=item.status;source.textContent=item.source;card.append(title,state,source);$('#research-coverage').append(card)}
 $('#research-sources').replaceChildren();for(const item of d.sources){const card=document.createElement('article');card.className='research-card';const img=document.createElement('img');if(item.image){img.src=item.image;img.alt=item.title;img.loading='lazy'}else img.hidden=true;const body=document.createElement('div');body.className='research-card-body';const title=document.createElement('strong');title.textContent=item.title;const kind=document.createElement('span');kind.className='source-kind';kind.textContent=item.kind;const status=document.createElement('span');status.className='research-status'+(item.status==='版本差异'?' different':'');status.textContent=item.status;const use=document.createElement('p');use.textContent=item.use;body.append(title,kind,status,use);if(item.url){const link=document.createElement('a');link.href=item.url;link.textContent='查看来源 ↗';link.target='_blank';link.rel='noopener';body.append(link)}card.append(img,body);$('#research-sources').append(card)}
 $('#research-decisions').replaceChildren();for(const m of d.modeling){const p=document.createElement('p');p.textContent=m.part+'｜依据：'+m.basis+'｜建模处理：'+m.action;$('#research-decisions').append(p)}$('#research-limits').textContent=d.limitations;
 }
 const match=$('#research-match');for(const product of products){const option=document.createElement('option');option.value=product.key;option.textContent=product.dossier.product+' · '+product.dossier.spec;match.append(option)}match.onchange=()=>$('#research-use-match').disabled=!match.value;
 $('#research-use-match').onclick=async()=>{const product=products.find(p=>p.key===match.value);if(!session||!product)return;session.product=product;session.generatedRecipe=null;session.dossier=product.dossier;session.manual=true;session.config={method:product.key,tolerance:35};renderResearch();await build();$('#researched-model-tools').scrollIntoView({block:'start',behavior:'smooth'})};
 return async function show(source,name,saved={}){const identified=source?await identifyProduct(source,name):{photo:null,product:null},photo=identified.photo;let product=saved.edit?products.find(p=>p.key===saved.config?.method):null;product ||=identified.product;
 session={name,source:photo?.originalSource||'',photo,product,dossier:saved.generatedRecipe?saved.research:product?.dossier||null,generatedRecipe:saved.generatedRecipe,generationId:saved.generationId,manual:false,config:{method:saved.generatedRecipe?'generated':product?.key||'pending-research',tolerance:35,physicalSize:saved.config?.physicalSize},extraSources:saved.extraSources||{}};
 match.value='';$('#research-use-match').disabled=true;$('#research-capacity').value='';renderResearch();$('#photo-create').textContent=saved.edit?'更新产品还原 →':'按此尺寸加入布景 →';$('#photo-create').disabled=true;const result=new Promise(resolve=>resolveFlow=resolve);dialog.showModal();dialog.scrollTop=0;size();animate();if(product||saved.generatedRecipe)await build();return result;
 };
}
